begin;
create table if not exists public.knowledge_questions (
 id integer primary key, version text not null default 'knowledge-100-v1', topic text not null,
 anchor text not null, content jsonb not null, correct integer not null check(correct between 0 and 3)
);
create table if not exists public.knowledge_runs (
 id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade,
 locale text not null check(locale in ('th','en')), version text not null default 'knowledge-100-v1',
 items jsonb not null check(jsonb_array_length(items)=100), answers jsonb not null default '[]',
 score integer not null default 0 check(score between 0 and 100),
 started_at timestamptz not null default clock_timestamp(), finished_at timestamptz,
 abandoned boolean not null default false
);
create table if not exists public.knowledge_results (
 id uuid primary key references public.knowledge_runs(id) on delete cascade,
 user_id uuid not null references auth.users(id) on delete cascade,
 version text not null, score integer not null check(score between 0 and 100),
 total integer not null default 100 check(total=100), elapsed_ms bigint not null check(elapsed_ms>=0),
 completed_at timestamptz not null
);
alter table public.knowledge_questions enable row level security;
alter table public.knowledge_runs enable row level security;
alter table public.knowledge_results enable row level security;
revoke all on public.knowledge_questions,public.knowledge_runs,public.knowledge_results from anon,authenticated;
-- No client table writes or answer-key reads; all transitions go through locked RPCs.
create or replace function public.knowledge_question(p_run public.knowledge_runs,p_index integer) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare item jsonb; q public.knowledge_questions; opts jsonb;
begin
 if p_index>=100 then return null; end if;
 item:=p_run.items->p_index;
 select * into strict q from public.knowledge_questions where id=(item->>'id')::int;
 select jsonb_agg(q.content->p_run.locale->'options'->(v.value::text)::int order by v.ordinality) into opts from jsonb_array_elements(item->'order') with ordinality v;
 return jsonb_build_object('index',p_index,'topic',q.topic,'question',q.content->p_run.locale->>'q','options',opts);
end $$;
create or replace function public.knowledge_state(p_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r public.knowledge_runs; saved boolean;
begin
 select * into r from public.knowledge_runs where id=p_id;
 if not found or r.abandoned or (r.user_id is not null and r.user_id is distinct from auth.uid()) then raise exception 'RUN_UNAVAILABLE'; end if;
 select exists(select 1 from public.knowledge_results where id=r.id) into saved;
 return jsonb_build_object('id',r.id,'locale',r.locale,'count',jsonb_array_length(r.answers),'score',r.score,
 'elapsed',floor(extract(epoch from (coalesce(r.finished_at,clock_timestamp())-r.started_at))*1000),
 'finished',r.finished_at is not null,'saved',saved,'ranked',r.user_id is not null,
 'history',r.answers,'question',public.knowledge_question(r,jsonb_array_length(r.answers)));
end $$;
create or replace function public.knowledge_start(p_locale text,p_previous uuid default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare rid uuid; items jsonb; q record; ord jsonb;
begin
 if p_locale not in ('en','th') then raise exception 'INVALID_LOCALE'; end if;
 if p_previous is not null then
 update public.knowledge_runs set abandoned=true where id=p_previous and finished_at is null and (user_id is null or user_id=auth.uid());
 end if;
 if auth.uid() is not null and (select count(*) from public.knowledge_runs where user_id=auth.uid() and started_at>clock_timestamp()-interval '1 minute')>=15 then raise exception 'PLEASE_WAIT'; end if;
 items:='[]';
 for q in select id from public.knowledge_questions where version='knowledge-100-v1' order by random() limit 100 loop
 select jsonb_agg(x.n) into ord from (select n from generate_series(0,3) n order by random()) x;
 items:=items||jsonb_build_array(jsonb_build_object('id',q.id,'order',ord));
 end loop;
 if jsonb_array_length(items)<>100 then raise exception 'QUESTION_BANK_NOT_READY'; end if;
 insert into public.knowledge_runs(user_id,locale,items) values(auth.uid(),p_locale,items) returning id into rid;
 return public.knowledge_state(rid);
end $$;
create or replace function public.knowledge_answer(p_id uuid,p_index integer,p_choice integer) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r public.knowledge_runs; q public.knowledge_questions; item jsonb; answer jsonb; correct_position integer; n integer;
begin
 if p_choice is null or p_choice not between 0 and 3 or p_index is null or p_index not between 0 and 99 then raise exception 'INVALID_ANSWER'; end if;
 select * into r from public.knowledge_runs where id=p_id for update;
 if not found or r.abandoned or (r.user_id is not null and r.user_id is distinct from auth.uid()) then raise exception 'RUN_UNAVAILABLE'; end if;
 n:=jsonb_array_length(r.answers);
 if p_index<n then
 if (r.answers->p_index->>'choice')::int<>p_choice then raise exception 'ANSWER_LOCKED'; end if;
 return public.knowledge_state(r.id); -- same request retry is idempotent
 end if;
 if p_index<>n or r.finished_at is not null then raise exception 'ANSWER_OUT_OF_ORDER'; end if;
 item:=r.items->p_index;
 select * into strict q from public.knowledge_questions where id=(item->>'id')::int;
 select v.ordinality::int-1 into correct_position from jsonb_array_elements(item->'order') with ordinality v where (v.value::text)::int=q.correct;
 answer:=public.knowledge_question(r,p_index)||jsonb_build_object('choice',p_choice,'correct',correct_position,'ok',p_choice=correct_position,'explanation',q.content->r.locale->>'explanation','anchor',q.anchor);
 update public.knowledge_runs set answers=answers||jsonb_build_array(answer),score=score+case when p_choice=correct_position then 1 else 0 end,
 finished_at=case when n=99 then clock_timestamp() else null end where id=r.id returning * into r;
 if r.finished_at is not null and r.user_id is not null then
 insert into public.knowledge_results(id,user_id,version,score,elapsed_ms,completed_at) values(r.id,r.user_id,r.version,r.score,floor(extract(epoch from(r.finished_at-r.started_at))*1000)::bigint,r.finished_at) on conflict(id) do nothing;
 end if;
 return public.knowledge_state(r.id);
end $$;
create or replace function public.knowledge_claim(p_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r public.knowledge_runs;
begin
 if auth.uid() is null then raise exception 'LOGIN_REQUIRED'; end if;
 select * into r from public.knowledge_runs where id=p_id for update;
 if not found or r.abandoned or r.finished_at is null or jsonb_array_length(r.answers)<>100 or (r.user_id is not null and r.user_id<>auth.uid()) then raise exception 'RUN_UNAVAILABLE'; end if;
 update public.knowledge_runs set user_id=auth.uid() where id=p_id;
 insert into public.knowledge_results(id,user_id,version,score,elapsed_ms,completed_at) values(r.id,auth.uid(),r.version,r.score,floor(extract(epoch from(r.finished_at-r.started_at))*1000)::bigint,r.finished_at) on conflict(id) do nothing;
 return public.knowledge_state(p_id);
end $$;
create or replace function public.knowledge_leaderboard() returns table(rank bigint,username text,score integer,elapsed_ms bigint,mine boolean)
language sql stable security definer set search_path='' as $$
 with best as (
 select distinct on (r.user_id) r.user_id,r.score,r.elapsed_ms,r.completed_at
 from public.knowledge_results r where r.version='knowledge-100-v1'
 order by r.user_id,r.score desc,r.elapsed_ms asc,r.completed_at asc
 ), ranked as (
 select row_number() over(order by b.score desc,b.elapsed_ms asc,b.completed_at asc,b.user_id) as rank,
 coalesce(u.username,'learner') as username,b.score,b.elapsed_ms,b.user_id=auth.uid() as mine
 from best b left join public.users u on u.id=b.user_id
 ) select * from ranked where rank<=50 or mine order by rank;
$$;
revoke all on function public.knowledge_question(public.knowledge_runs,integer) from public,anon,authenticated;
revoke all on function public.knowledge_start(text,uuid),public.knowledge_state(uuid),public.knowledge_answer(uuid,integer,integer),public.knowledge_claim(uuid),public.knowledge_leaderboard() from public,anon,authenticated;
grant execute on function public.knowledge_start(text,uuid),public.knowledge_state(uuid),public.knowledge_answer(uuid,integer,integer),public.knowledge_leaderboard() to anon,authenticated;
grant execute on function public.knowledge_claim(uuid) to authenticated;

