(29,'branches','branches','{"th":{"q":"ซื้อ Expansion License ด้วยอะไร?","options":["STANDARD","คะแนนเกม","ยอดติดตาม","ทองคำจริงส่งทางไปรษณีย์"],"explanation":"การซื้อ Expansion License ใช้ STANDARD และเผาทั้งหมดเพื่อเปิด Branch เพิ่ม สาขาแบ่งการจัดสรรตามสัดส่วนจำนวนสาขารวม"},"en":{"q":"What pays for an expansion license?","options":["STANDARD","Quiz points","Followers","Mailed physical gold"],"explanation":"Expansion licenses are paid in STANDARD, entirely burned, to open branches. Issuance is divided proportionally among branches."}}'::jsonb,0),
