(71,'net-flow','net-flow','{"th":{"q":"ตัวอย่างหนึ่ง epoch: ซื้อเข้า 20 ETH ขายออก 8 ETH กระแสสุทธิเท่าไร?","options":["12 ETH","28 ETH","22 ETH","7 ETH"],"explanation":"กระแสสุทธิ = 20 − 8 = 12 ETH นี่เป็นตัวอย่างหนึ่ง epoch ไม่ใช่สัญญาณสอง epoch ทั้งหมด"},"en":{"q":"Illustrative epoch: buys bring 20 ETH, sells take 8 ETH. What is net flow?","options":["12 ETH","28 ETH","22 ETH","7 ETH"],"explanation":"Net flow = 20 − 8 = 12 ETH. This is one epoch, not the complete two-epoch policy signal."}}'::jsonb,0),
